#[path = "../syntax.rs"]
mod syntax;
#[path = "../tokens.rs"]
mod tokens;

use std::error::Error;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use proc_macro2::TokenStream;
use syn::Item;

const HEADER: &str =
    "// @generated by `cargo run -p m2-syn-macros --bin generate`; do not edit.\n\n";

fn main() -> Result<(), Box<dyn Error>> {
    let check = match std::env::args().skip(1).collect::<Vec<_>>().as_slice() {
        [] => false,
        [argument] if argument == "--check" => true,
        _ => return Err("usage: generate [--check]".into()),
    };
    let repository = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("macro crate is inside the repository")
        .to_owned();
    let source_path = repository.join("src/nodes.rs");
    let source = fs::read_to_string(&source_path)?;
    let input = syntax_input(&source, &source_path)?;
    let generated = syntax::generate(input)?;
    let directory = repository.join("src/gen");

    if !check {
        fs::create_dir_all(&directory)?;
    }

    let mut stale = Vec::new();
    for (name, tokens) in generated.files() {
        let contents = rustfmt(&format!("{HEADER}{tokens}"))?;
        let path = directory.join(name);
        if check {
            if fs::read_to_string(&path).ok().as_deref() != Some(&contents) {
                stale.push(path);
            }
        } else {
            fs::write(path, contents)?;
        }
    }

    if stale.is_empty() {
        Ok(())
    } else {
        let paths = stale
            .iter()
            .map(|path| path.display().to_string())
            .collect::<Vec<_>>()
            .join(", ");
        Err(format!("generated files are stale: {paths}").into())
    }
}

fn syntax_input(source: &str, path: &Path) -> Result<TokenStream, Box<dyn Error>> {
    let file = syn::parse_file(source)?;
    file.items
        .into_iter()
        .find_map(|item| match item {
            Item::Macro(item) if item.mac.path.is_ident("syntax_schema") => Some(item.mac.tokens),
            _ => None,
        })
        .ok_or_else(|| {
            format!(
                "{} does not contain a `syntax_schema!` block",
                path.display()
            )
            .into()
        })
}

fn rustfmt(source: &str) -> Result<String, Box<dyn Error>> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    child
        .stdin
        .take()
        .expect("piped rustfmt stdin")
        .write_all(source.as_bytes())?;
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }
    Ok(String::from_utf8(output.stdout)?.replace("Token ! [", "Token!["))
}
